Ext._define('ceaf.capacitation.participants.Window', {
    extend: 'core.RestfulWindow',

    rest: 'ceaf.capacitation.participants.Restful',

    width: 700,


    getName: function(cfg) {
        if(!this._getNameField){
            this._getNameField = new Ext._create('Ext.form.TextField', {
            
                width: 450,
                maxLength: 256, 
                allowBlank: false, 
                fieldLabel: "Nome", 
                name: "name", 
                hiddenName: "name",
                }
            );
        }
        return this._getNameField;
    },

    getActiveAction: function(cfg) {
        if(!this._activeAction) {
            console.log(cfg.values)
            this._activeAction = Ext._create('Ext.form.Checkbox', {
                allowBlank: true,
                checked: cfg.values.pk ? cfg.values.employee?true:false :true,
                boxLabel: 'O Participante é servidor?'
            });
            
            this._activeAction.on({
                scope: this,
                render: function(wnd) {
                    console.log(wnd)
                    if (wnd.checked){
                        this.getName().hide()
                        this.getName().disable()
                        this.getEmployee().show()
                        this.getEmployee().enable()
                        if(cfg.values.employee){
                            this.getEmployee().readOnly = true;
                            this._activeAction.disable()
                        }else{
                            this.getEmployee().readOnly = false;
                            this._activeAction.enable();
                        }
                        
                    }else{
                        this.getName().show()
                        this.getName().enable()
                        this.getEmployee().hide()
                        this.getEmployee().setValue(undefined)
                        this.getEmployee().disable()
                        if(cfg.values.pk){
                            this.getName().readOnly = true;
                            this._activeAction.disable()
                        }else{
                            this.getName().readOnly = false;
                            this._activeAction.enable();
                        }
                    }
                    
                },
                
                check: function(checked) {
                    if(checked.checked) {
                        this.getName().hide()
                        this.getName().disable()
                        this.getEmployee().show()
                        this.getEmployee().enable()
                    }
                    else {
                        this.getName().show()
                        this.getName().enable()
                        this.getEmployee().hide()
                        this.getEmployee().setValue(undefined)
                        this.getEmployee().disable()
                    }
                }
            });

        }

        return this._activeAction;
    },

    getEmployee: function() {
        if (!this._employee) {
            this._employee = Ext._create('core.fields.AutocompleteField', {
                fieldLabel: 'Servidor',
                allowBlank: true,
                rest: "rh.employee.Restful",
                name: "employee",
                displayField: 'unicode_status',
                gridConfig: {
                    configOrderToolBar: ['search', '->'],
                    hideColumns: ['departure_unicode', 'elective_unicode', 'pk',  'user', 'tipo', 'pessoa_fisica',
                    'email', 'vpi', 'data_referencia_ferias', 'chefe_imediato', 'chefe_imediato_unicode', 'effective_unicode',
                    'data_exercicio','data_posse', 'data_desligamento', 'created_at', 'modified_at', 'created_by_unicode',
                    'modified_by_unicode', 'event_esocial','commission_unicode',],
                    columnAction: false,
                },
            });
        }

        return this._employee;
    },


    getFormPanel: function(cfg) {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                frame: true,
                items: [
                    this.getActiveAction(cfg),
                    this.getName(),
                    this.getEmployee(),
                    
                    {
                        xtype: 'choicefield',
                        fieldLabel: 'Tipo de Participação',
                        allowBlank: true,
                        lazyRender: true,
                        name: 'type_participant',
                        hiddenName: 'type_participant',
                        choiceId: 'ceaf.TYPE_CEAF_PARTICIPANT',
                        width: 150
                    },

            ]
            });

        return this._formPanel;
    }
});

